<div class="card"><h3>Nová pravidelná fakturace</h3><form class="form" method="post" action="/recurring"><input type="hidden" name="_csrf" value="<?=App\Core\Auth::csrf()?>"><div class="row"><div class="field"><label>Zákazník</label><select name="customer_id" required><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=View::e($c['company_name']?:trim(($c['first_name']??'').' '.($c['last_name']??'')))?></option><?php endforeach;?></select></div><div class="field"><label>První vystavení</label><input type="date" name="next_run" value="<?=date('Y-m-d')?>"></div></div><div class="row"><div class="field"><label>Interval</label><select name="interval_type"><option value="month">měsíc</option><option value="quarter">čtvrtletí</option><option value="year">rok</option></select></div><div class="field"><label>Počet intervalů</label><input type="number" name="interval_value" value="1" min="1"></div></div><div class="row"><div class="field"><label>Název položky</label><input name="item_name" required></div><div class="field"><label>Cena bez DPH</label><input type="number" step="0.01" name="unit_price" required></div></div><div class="row"><div class="field"><label>Množství</label><input type="number" step="0.01" name="quantity" value="1"></div><div class="field"><label>DPH %</label><input type="number" step="0.01" name="vat_rate" value="21"></div></div><label><input type="checkbox" name="send_email" checked> odeslat e-mailem, pokud má zákazník e-mail</label><button class="btn primary">Uložit pravidlo</button></form></div><div class="card" style="margin-top:16px"><h3>Pravidla</h3><div class="tablewrap"><table class="table"><tr><th>Zákazník</th><th>Interval</th><th>Další běh</th><th>Aktivní</th></tr><?php foreach($rows as $r):?><tr><td><?=View::e($r['company_name']?:trim(($r['first_name']??'').' '.($r['last_name']??'')))?></td><td><?=View::e($r['interval_type'])?> / <?=View::e($r['interval_value'])?></td><td><?=View::e($r['next_run'])?></td><td><?=((int)$r['active'])?'Ano':'Ne'?></td></tr><?php endforeach;?></table></div></div>
